    92→pub async fn execute(args: StartArgs) -> Result<()> {
    93→    // Expand tilde in paths
    94→    let work_dir = expand_tilde(&args.work_dir);
    95→    let log_dir = expand_tilde(&args.log_dir);
    96→    let project_dir = expand_tilde(&args.project_dir);
    97→
    98→    // Check if cluster already running
    99→    if state_exists(&work_dir) {
   100→        output::error("Cluster is already running. Use 'distributed stop' to stop it first.");
   101→        return Err(anyhow::anyhow!("Cluster already running"));
   102→    }
   103→
   104→    // Build configuration
   105→    let mut config = ClusterConfig::default();
   106→    config.num_executors = args.executors;
   107→    config.scheduler.http_port = args.scheduler_http;
   108→    config.scheduler.flight_port = args.scheduler_flight;
   109→    config.scheduler.node_port = args.scheduler_node;
   110→    config.executors.base_http_port = args.executor_http;
   111→    config.executors.base_node_port = args.executor_node;
   112→    config.paths.log_dir = log_dir;
   113→    config.paths.work_dir = work_dir;
   114→    config.paths.project_dir = project_dir;
   115→    if let Some(spiced_path) = args.spiced_path {
   116→        config.paths.spiced_path = expand_tilde(&spiced_path);
   117→    }
   118→    config.detach = args.detach;
   119→    config.skip_tls_init = args.no_tls_init;
   120→    config.skip_health_check = args.no_health_check;
   121→
   122→    // Validate spiced binary exists
   123→    if !config.paths.spiced_path.exists() {
   124→        output::error(&format!(
   125→            "spiced binary not found at: {}",
   126→            config.paths.spiced_path.display()
   127→        ));
   128→        output::info("Please install Spice.ai or specify the correct path with --spiced-path");
   129→        return Err(anyhow::anyhow!("spiced binary not found"));
   130→    }
   131→
   132→    output::info("Starting distributed Spice cluster...");
   133→
   134→    // Initialize TLS if needed
   135→    if !config.skip_tls_init {
   136→        output::info("Initializing TLS certificates...");
   137→        tls::ensure_tls_initialized().context("Failed to initialize TLS")?;
   138→
   139→        // Generate certificates for scheduler and executors
   140→        // Note: scheduler uses "scheduler1" as the cert name to match bash script convention
   141→        let mut node_names = vec!["scheduler1"];
   142→        let executor_names: Vec<String> = (0..config.num_executors)
   143→            .map(|i| config.executor_name(i))
   144→            .collect();
   145→        let executor_refs: Vec<&str> = executor_names.iter().map(String::as_str).collect();
   146→        node_names.extend(&executor_refs);
   147→
   148→        tls::ensure_certificates(&node_names).context("Failed to generate certificates")?;
   149→    }
   150→
   151→    // Start scheduler
   152→    output::info(&format!(
   153→        "Starting scheduler on port {}...",
   154→        config.scheduler.http_port
   155→    ));
   156→    let scheduler_node = process::start_scheduler(&config).context("Failed to start scheduler")?;
   157→
