use anyhow::{Context, Result};
use clap::Args;
use serde::Serialize;
use std::path::PathBuf;

use crate::cluster::{health::*, process, state::*};
use crate::output;

/// Expand tilde in path to home directory.
fn expand_tilde(path: &PathBuf) -> PathBuf {
